<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Http\Requests\ClientRequest; use App\Models\Client; use App\Services\AuditService;
class ClientController extends Controller { public function index(){return view('admin.clients.index',['clients'=>Client::withCount('instances')->latest()->paginate(20)]);} public function create(){return view('admin.clients.form',['client'=>new Client]);} public function store(ClientRequest $r,AuditService $a){$c=Client::create($r->validated()+['active'=>true]);$a->record('create_client','Cliente creado.',$c);return redirect()->route('clients.show',$c)->with('success','Cliente creado.');} public function show(Client $client){$client->load('instances');return view('admin.clients.show',compact('client'));} public function edit(Client $client){return view('admin.clients.form',compact('client'));} public function update(ClientRequest $r,Client $client,AuditService $a){$client->update($r->validated());$a->record('update_client','Cliente actualizado.',$client);return redirect()->route('clients.show',$client)->with('success','Cliente actualizado.');} public function toggle(Client $client,AuditService $a){$client->update(['active'=>!$client->active]);$a->record('toggle_client','Estado de cliente actualizado.',$client);return back()->with('success','Estado actualizado.');} }
